// @flow
import * as React from 'react';
import { Trans } from '@lingui/macro';
import VariablesEditorDialog, {
  type VariableDialogOpeningProps,
} from './VariablesEditorDialog';
import { type HotReloadPreviewButtonProps } from '../HotReload/HotReloadPreviewButton';
import { ProjectScopedContainersAccessor } from '../InstructionOrExpression/EventsScope';

type Props = {|
  open: boolean,
  project: gdProject,
  projectScopedContainersAccessor: ProjectScopedContainersAccessor,
  objectName: string | null,
  initialInstances: gdInitialInstancesContainer | null,
  variablesContainer: gdVariablesContainer,
  onApply: (selectedVariableName: string | null) => void,
  onCancel: () => void,
  hotReloadPreviewButtonProps: HotReloadPreviewButtonProps | null,
  initiallySelectedVariable: VariableDialogOpeningProps | null,
  onComputeAllVariableNames: () => Array<string>,
  isListLocked: boolean,
|};

const ObjectVariablesDialog = ({
  project,
  objectName,
  initialInstances,
  variablesContainer,
  open,
  onCancel,
  onApply,
  hotReloadPreviewButtonProps,
  initiallySelectedVariable,
  projectScopedContainersAccessor,
  onComputeAllVariableNames,
  isListLocked,
}: Props): React.Node => {
  const tabs = React.useMemo(
    () => [
      {
        id: 'object-variables',
        label: '',
        variablesContainer: variablesContainer,
        emptyPlaceholderTitle: <Trans>Add your first object variable</Trans>,
        emptyPlaceholderDescription: (
          <Trans>
            These variables hold additional information on an object.
          </Trans>
        ),
        onComputeAllVariableNames,
      },
    ],
    [onComputeAllVariableNames, variablesContainer]
  );

  return (
    <VariablesEditorDialog
      project={project}
      projectScopedContainersAccessor={projectScopedContainersAccessor}
      objectName={objectName}
      initialInstances={initialInstances}
      open={open}
      onCancel={onCancel}
      onApply={onApply}
      title={<Trans>{objectName} variables</Trans>}
      // $FlowFixMe[incompatible-type]
      tabs={tabs}
      initiallySelectedVariable={initiallySelectedVariable}
      helpPagePath={'/all-features/variables/object-variables'}
      hotReloadPreviewButtonProps={hotReloadPreviewButtonProps}
      id="object-variables-dialog"
      isListLocked={isListLocked}
    />
  );
};

export default ObjectVariablesDialog;
